INSERT INTO `attractions` (`id`, `zone_id`, `name`, `description`, `image`, `age`, `badge`, `position`, `is_active`, `is_special`, `ticket_type_id`, `created_at`, `updated_at`) VALUES (1,1,'{\"en\": \"Free jump\", \"es\": \"Saltos libres\", \"fr\": \"Saut libre\"}','{\"en\": \"Wall-to-wall trampolines to jump non-stop from side to side.\", \"es\": \"Trampolines de pared a pared para saltar sin parar de un lado a otro.\", \"fr\": \"Trampolines mur à mur pour sauter sans arrêt d\'un côté à l\'autre.\"}','images/attractions/jump_saltos_libres.webp','{\"en\": \"All ages\", \"es\": \"Todos los públicos\", \"fr\": \"Tous publics\"}',NULL,1,1,0,NULL,'2026-08-19 14:04:29','2026-08-19 14:04:29'),(2,1,'{\"en\": \"Cloud jump\", \"es\": \"Salto a la nube\", \"fr\": \"Saut dans le nuage\"}','{\"en\": \"Launch off the trampoline onto a giant airbag. Soft landing.\", \"es\": \"Lánzate desde el trampolín a un colchón de aire gigante. Aterrizaje blando.\", \"fr\": \"Lance-toi du trampoline sur un coussin d\'air géant. Atterrissage tout doux.\"}','images/attractions/jump_saltos_de_nube.webp','{\"en\": \"+8 yrs\", \"es\": \"+8 años\", \"fr\": \"+8 ans\"}','{\"en\": \"XL\", \"es\": \"XL\", \"fr\": \"XL\"}',2,1,1,NULL,'2026-08-19 14:04:29','2026-08-19 14:04:32'),(3,1,'{\"en\": \"Zipline\", \"es\": \"Tirolina\", \"fr\": \"Tyrolienne\"}','{\"en\": \"Cross the room hanging from the zipline, above the attractions.\", \"es\": \"Cruza la sala colgado de la tirolina, por encima de las atracciones.\", \"fr\": \"Traverse la salle suspendu à la tyrolienne, au-dessus des attractions.\"}','images/attractions/jump_tirolina_jump.webp','{\"en\": \"+10 yrs\", \"es\": \"+10 años\", \"fr\": \"+10 ans\"}',NULL,3,1,0,NULL,'2026-08-19 14:04:29','2026-08-19 14:04:32'),(4,1,'{\"en\": \"Basket Jump\", \"es\": \"Basket Jump\", \"fr\": \"Basket Jump\"}','{\"en\": \"Jump off the trampoline and dunk the hoop like a pro.\", \"es\": \"Salta del trampolín y machaca el aro como un profesional.\", \"fr\": \"Saute du trampoline et dunk comme un pro.\"}','images/attractions/jump_basket_jump.webp','{\"en\": \"+8 yrs\", \"es\": \"+8 años\", \"fr\": \"+8 ans\"}',NULL,4,1,0,NULL,'2026-08-19 14:04:29','2026-08-19 14:04:29'),(5,1,'{\"en\": \"Boxing Jump\", \"es\": \"Boxing Jump\", \"fr\": \"Boxing Jump\"}','{\"en\": \"Beam duel: knock your rival into the foam and stay standing.\", \"es\": \"Duelo sobre la viga: derriba a tu rival al foam y aguanta en pie.\", \"fr\": \"Duel sur la poutre : fais tomber ton rival dans la mousse et reste debout.\"}','images/attractions/jump_boxing_jump.webp','{\"en\": \"+10 yrs\", \"es\": \"+10 años\", \"fr\": \"+10 ans\"}',NULL,5,1,0,NULL,'2026-08-19 14:04:29','2026-08-19 14:04:29'),(6,1,'{\"en\": \"Sweeper\", \"es\": \"Barredora\", \"fr\": \"Balayeuse\"}','{\"en\": \"Jump the spinning arm sweeping the floor or you will fall.\", \"es\": \"Salta el brazo giratorio que barre la pista o caerás al suelo.\", \"fr\": \"Saute le bras tournant qui balaie la piste ou tu tomberas.\"}','images/attractions/jump_barredora1.webp','{\"en\": \"+8 yrs\", \"es\": \"+8 años\", \"fr\": \"+8 ans\"}',NULL,6,1,0,NULL,'2026-08-19 14:04:29','2026-08-19 14:04:29'),(7,1,'{\"en\": \"Spinning sweeper\", \"es\": \"Barredora circular\", \"fr\": \"Balayeuse circulaire\"}','{\"en\": \"The sweeper, now in a circle: keep jumping so you do not fall.\", \"es\": \"La barredora, ahora en círculo: salta sin parar para no caer.\", \"fr\": \"La balayeuse, version circulaire : saute sans arrêt pour ne pas tomber.\"}','images/attractions/jump_barredora_circular.webp','{\"en\": \"+8 yrs\", \"es\": \"+8 años\", \"fr\": \"+8 ans\"}',NULL,7,1,0,NULL,'2026-08-19 14:04:29','2026-08-19 14:04:29'),(8,1,'{\"en\": \"Parkour & Free Run\", \"es\": \"Parkour & Free Run\", \"fr\": \"Parkour & Free Run\"}','{\"en\": \"Soft obstacle circuit to train your parkour moves.\", \"es\": \"Circuito de obstáculos blandos para entrenar tus saltos de parkour.\", \"fr\": \"Parcours d\'obstacles en mousse pour entraîner tes mouvements de parkour.\"}','images/attractions/jump_parkour.webp','{\"en\": \"+12 yrs\", \"es\": \"+12 años\", \"fr\": \"+12 ans\"}',NULL,8,1,0,NULL,'2026-08-19 14:04:29','2026-08-19 14:04:29'),(9,1,'{\"en\": \"Vertical climbing\", \"es\": \"Escalada vertical\", \"fr\": \"Escalade verticale\"}','{\"en\": \"Climbing wall with a safety mat to reach the very top.\", \"es\": \"Pared de escalada con colchoneta de seguridad para llegar a lo más alto.\", \"fr\": \"Mur d\'escalade avec tapis de sécurité pour atteindre le sommet.\"}','images/attractions/jump_escalada_vertical.webp','{\"en\": \"+8 yrs\", \"es\": \"+8 años\", \"fr\": \"+8 ans\"}',NULL,9,1,0,NULL,'2026-08-19 14:04:29','2026-08-19 14:04:29'),(10,1,'{\"en\": \"Balance beam\", \"es\": \"Equilibrio\", \"fr\": \"Équilibre\"}','{\"en\": \"Cross the balance beam without losing your footing.\", \"es\": \"Cruza la viga de equilibrio sin perder pie.\", \"fr\": \"Traverse la poutre d\'équilibre sans perdre pied.\"}','images/attractions/jump_equilibrio_.webp','{\"en\": \"+6 yrs\", \"es\": \"+6 años\", \"fr\": \"+6 ans\"}',NULL,10,1,0,NULL,'2026-08-19 14:04:29','2026-08-19 14:04:29'),(11,1,'{\"en\": \"Pole circuit\", \"es\": \"Circuito de postes\", \"fr\": \"Parcours de poteaux\"}','{\"en\": \"Dodge the poles at full speed from end to end.\", \"es\": \"Esquiva los postes a toda velocidad de un extremo a otro.\", \"fr\": \"Esquive les poteaux à toute vitesse d\'un bout à l\'autre.\"}','images/attractions/jump_circuito_de_postes.webp','{\"en\": \"+6 yrs\", \"es\": \"+6 años\", \"fr\": \"+6 ans\"}',NULL,11,1,0,NULL,'2026-08-19 14:04:29','2026-08-19 14:04:29'),(12,1,'{\"en\": \"High circuit\", \"es\": \"Circuito High\", \"fr\": \"Parcours en hauteur\"}','{\"en\": \"An elevated circuit for the boldest.\", \"es\": \"Circuito en altura para los más atrevidos.\", \"fr\": \"Un parcours en hauteur pour les plus audacieux.\"}','images/attractions/jump_circuito_high.webp','{\"en\": \"+12 yrs\", \"es\": \"+12 años\", \"fr\": \"+12 ans\"}','{\"en\": \"PRO\", \"es\": \"PRO\", \"fr\": \"PRO\"}',12,1,0,NULL,'2026-08-19 14:04:29','2026-08-19 14:04:29'),(13,1,'{\"en\": \"Mat slide\", \"es\": \"Tobogán colchoneta\", \"fr\": \"Toboggan à tapis\"}','{\"en\": \"Slide down the big slide on a mat.\", \"es\": \"Deslízate por el gran tobogán sobre la colchoneta.\", \"fr\": \"Glisse sur le grand toboggan avec un tapis.\"}','images/attractions/jump_tobogan_colchone.webp','{\"en\": \"All ages\", \"es\": \"Todos los públicos\", \"fr\": \"Tous publics\"}',NULL,13,1,0,NULL,'2026-08-19 14:04:29','2026-08-19 14:04:29'),(14,1,'{\"en\": \"Hit the target\", \"es\": \"Atina la bola\", \"fr\": \"Vise la cible\"}','{\"en\": \"Test your aim by throwing at the targets.\", \"es\": \"Pon a prueba tu puntería lanzando a las dianas.\", \"fr\": \"Teste ta précision en visant les cibles.\"}','images/attractions/jump_atina_bal.webp','{\"en\": \"All ages\", \"es\": \"Todos los públicos\", \"fr\": \"Tous publics\"}',NULL,14,1,0,NULL,'2026-08-19 14:04:29','2026-08-19 14:04:29'),(15,1,'{\"en\": \"Bee Jump\", \"es\": \"Bee Jump\", \"fr\": \"Bee Jump\"}','{\"en\": \"Bounce non-stop on the bee trampoline.\", \"es\": \"Salta y rebota sin parar en el trampolín de la abeja.\", \"fr\": \"Rebondis sans arrêt sur le trampoline de l\'abeille.\"}','images/attractions/jump_bee.webp','{\"en\": \"All ages\", \"es\": \"Todos los públicos\", \"fr\": \"Tous publics\"}',NULL,15,1,0,NULL,'2026-08-19 14:04:29','2026-08-19 14:04:29'),(16,2,'{\"en\": \"Ball pool\", \"es\": \"Piscina de bolas\", \"fr\": \"Piscine à balles\"}','{\"en\": \"More than 10,000 soft balls to dive, hide and swim in.\", \"es\": \"Más de 10.000 bolas blanditas para tirarse, esconderse y nadar.\", \"fr\": \"Plus de 10 000 balles toutes douces pour plonger, se cacher et nager.\"}','images/attractions/kids_piscina_de_bolas.webp','{\"en\": \"1 — 7 yrs\", \"es\": \"1 — 7 años\", \"fr\": \"1 — 7 ans\"}',NULL,1,1,0,NULL,'2026-08-19 14:04:29','2026-08-19 14:04:29'),(17,2,'{\"en\": \"Slides\", \"es\": \"Toboganes\", \"fr\": \"Toboggans\"}','{\"en\": \"Colourful slides that end in a giant cushion.\", \"es\": \"Toboganes de colores que terminan en un cojín gigante.\", \"fr\": \"Toboggans colorés qui finissent sur un coussin géant.\"}','images/attractions/kids_tobganes.webp','{\"en\": \"2 — 7 yrs\", \"es\": \"2 — 7 años\", \"fr\": \"2 — 7 ans\"}','{\"en\": \"Big\", \"es\": \"Grande\", \"fr\": \"Grand\"}',2,1,0,NULL,'2026-08-19 14:04:29','2026-08-19 14:04:29'),(18,2,'{\"en\": \"Ball slide\", \"es\": \"Tobogán de bolas\", \"fr\": \"Toboggan à balles\"}','{\"en\": \"A slide that ends straight in the ball pool.\", \"es\": \"Un tobogán que acaba directo en la piscina de bolas.\", \"fr\": \"Un toboggan qui finit droit dans la piscine à balles.\"}','images/attractions/kids_tobogan_bolas.webp','{\"en\": \"2 — 7 yrs\", \"es\": \"2 — 7 años\", \"fr\": \"2 — 7 ans\"}',NULL,3,1,0,NULL,'2026-08-19 14:04:29','2026-08-19 14:04:29'),(19,2,'{\"en\": \"Block castle\", \"es\": \"Castillo de bloques\", \"fr\": \"Château de blocs\"}','{\"en\": \"Build and climb the giant block castle.\", \"es\": \"Construye y trepa por el castillo de bloques gigantes.\", \"fr\": \"Construis et grimpe le château de blocs géants.\"}','images/attractions/kids_castillo_lego.webp','{\"en\": \"1 — 6 yrs\", \"es\": \"1 — 6 años\", \"fr\": \"1 — 6 ans\"}',NULL,4,1,0,NULL,'2026-08-19 14:04:29','2026-08-19 14:04:29'),(20,2,'{\"en\": \"Obstacle circuit\", \"es\": \"Circuito de obstáculos\", \"fr\": \"Parcours d\'obstacles\"}','{\"en\": \"Soft foam shapes to crawl, climb and take first jumps.\", \"es\": \"Espumas blandas para gatear, trepar y dar los primeros saltos.\", \"fr\": \"Mousses douces pour ramper, grimper et faire les premiers sauts.\"}','images/attractions/kids_circuito_obstaculos.webp','{\"en\": \"1 — 4 yrs\", \"es\": \"1 — 4 años\", \"fr\": \"1 — 4 ans\"}','{\"en\": \"Baby\", \"es\": \"Baby\", \"fr\": \"Bébé\"}',5,1,0,NULL,'2026-08-19 14:04:29','2026-08-19 14:04:29'),(21,2,'{\"en\": \"Rocket 360\", \"es\": \"Cohete 360\", \"fr\": \"Fusée 360\"}','{\"en\": \"Spin and spin on the rocket 360, laughing all the way.\", \"es\": \"Gira y gira en el cohete 360 sin parar de reír.\", \"fr\": \"Tourne et tourne sur la fusée 360 en riant.\"}','images/attractions/kids_cohete360.webp','{\"en\": \"3 — 7 yrs\", \"es\": \"3 — 7 años\", \"fr\": \"3 — 7 ans\"}',NULL,6,1,0,NULL,'2026-08-19 14:04:29','2026-08-19 14:04:29'),(22,2,'{\"en\": \"Crazy tunnel\", \"es\": \"Túnel loco\", \"fr\": \"Tunnel fou\"}','{\"en\": \"A padded tunnel that crosses the Kids zone end to end.\", \"es\": \"Un túnel mullido que cruza la zona Kids de extremo a extremo.\", \"fr\": \"Un tunnel rembourré qui traverse la zone Kids d\'un bout à l\'autre.\"}','images/attractions/kids_crazy_tunel.webp','{\"en\": \"2 — 6 yrs\", \"es\": \"2 — 6 años\", \"fr\": \"2 — 6 ans\"}',NULL,7,1,0,NULL,'2026-08-19 14:04:29','2026-08-19 14:04:29'),(23,2,'{\"en\": \"Football pitch\", \"es\": \"Campo de fútbol\", \"fr\": \"Terrain de foot\"}','{\"en\": \"Score goals on the padded mini football pitch.\", \"es\": \"Marca goles en el mini campo de fútbol acolchado.\", \"fr\": \"Marque des buts sur le mini terrain de foot rembourré.\"}','images/attractions/kids_campo_futrbol.webp','{\"en\": \"3 — 12 yrs\", \"es\": \"3 — 12 años\", \"fr\": \"3 — 12 ans\"}',NULL,8,1,0,NULL,'2026-08-19 14:04:29','2026-08-19 14:04:29');
