/*!40000 ALTER TABLE `faqs` DISABLE KEYS */;
INSERT INTO `faqs` (`id`, `question`, `answer`, `position`, `is_active`, `created_at`, `updated_at`) VALUES (1,'{\"en\": \"Do I need to book?\", \"es\": \"¿Hace falta reservar?\", \"fr\": \"Faut-il réserver ?\"}','{\"en\": \"You can just walk in and buy your ticket at reception. Booking gets you in at your time, and at weekends it is the only way to keep it.\", \"es\": \"Puedes venir directo y sacar la entrada en recepción. Reservando entras a tu hora, y los findes es la única forma de tenerla guardada.\", \"fr\": \"Tu peux venir directement et prendre ton billet à l\'accueil. En réservant, tu entres à ton heure, et le week-end c\'est la seule façon de la garder.\"}',1,1,'2026-08-19 14:04:30','2026-09-10 11:41:36'),(2,'{\"en\": \"Can I cancel or change the day?\", \"es\": \"¿Puedo cancelar o cambiar de día?\", \"fr\": \"Puis-je annuler ou changer de jour ?\"}','{\"en\": \"Yes. Call or write to us and we will move it. If you end up paying less, we refund the difference. The deadlines are in our Terms.\", \"es\": \"Sí. Llámanos o escríbenos y lo movemos. Si acabas pagando menos, te devolvemos la diferencia. Los plazos están en nuestras Condiciones.\", \"fr\": \"Oui. Appelle-nous ou écris-nous et on le déplace. Si tu finis par payer moins, on te rembourse la différence. Les délais sont dans nos Conditions.\"}',2,1,'2026-08-19 14:04:30','2026-09-10 11:41:36'),(3,'{\"en\": \"Is there parking?\", \"es\": \"¿Hay parking?\", \"fr\": \"Y a-t-il un parking ?\"}','{\"en\": \"Yes: on the street, right in front of the park, and it is free.\", \"es\": \"Sí: en la calle, justo delante del parque, y es gratis.\", \"fr\": \"Oui : dans la rue, juste devant le parc, et c\'est gratuit.\"}',3,1,'2026-08-19 14:04:30','2026-09-10 11:41:36'),(4,'{\"en\": \"Do you do group rates?\", \"es\": \"¿Hacéis precio para grupos?\", \"fr\": \"Faites-vous des tarifs de groupe ?\"}','{\"en\": \"Yes: schools, companies and adult groups, tailored to you and also outside opening hours. Write to us from Contact or see our Services page.\", \"es\": \"Sí: colegios, empresas y grupos de adultos, a medida y también fuera de nuestro horario. Escríbenos desde Contacto o mira la página de Servicios.\", \"fr\": \"Oui : écoles, entreprises et groupes d\'adultes, sur mesure et aussi hors horaires. Écris-nous depuis Contact ou vois la page Services.\"}',4,1,'2026-08-19 14:04:30','2026-09-10 11:41:36'),(5,'{\"en\": \"And if it rains?\", \"es\": \"¿Y si llueve?\", \"fr\": \"Et s\'il pleut ?\"}','{\"en\": \"All the better: the park is indoors, climate-controlled and at 22 °C all year round.\", \"es\": \"Mejor para vosotros: el parque es interior, climatizado y a 22 °C todo el año.\", \"fr\": \"Tant mieux : le parc est en intérieur, climatisé et à 22 °C toute l\'année.\"}',5,1,'2026-08-19 14:04:30','2026-09-10 11:41:36');
/*!40000 ALTER TABLE `faqs` ENABLE KEYS */;

/*!40000 ALTER TABLE `landing_services` DISABLE KEYS */;
INSERT INTO `landing_services` (`id`, `slug`, `accent_word`, `title`, `body`, `zone_label`, `specs`, `price_table`, `nav_subtitle`, `image`, `ticket_type_id`, `position`, `is_active`, `show_in_nav`, `created_at`, `updated_at`) VALUES (1,'excursionescolegio','{\"en\": \"School\", \"es\": \"Colegio\", \"fr\": \"École\"}','{\"en\": \"School trips\", \"es\": \"Excursiones de colegio\", \"fr\": \"Sorties scolaires\"}','{\"en\": \"We host school visits with monitors and all the gear, in 2- or 3-hour sessions outside our public opening hours. Group pricing, and we adapt to your class size and calendar.\", \"es\": \"Organizamos visitas para centros educativos con monitores y todo el material, en sesiones de 2 o 3 horas fuera de nuestro horario de apertura al público. Precios especiales por grupo; nos adaptamos al número de alumnos y a vuestro calendario.\", \"fr\": \"On accueille les sorties scolaires avec moniteurs et tout le matériel, lors de séances de 2 ou 3 heures en dehors de nos horaires d\'ouverture au public. Tarifs de groupe et on s\'adapte au nombre d\'élèves et à votre calendrier.\"}','{\"en\": \"Kids + Jump\", \"es\": \"Kids + Jump\", \"fr\": \"Kids + Jump\"}','{\"en\": [{\"label\": \"Duration\", \"value\": \"2 or 3 hours\"}, {\"label\": \"Hours\", \"value\": \"Outside opening\"}], \"es\": [{\"label\": \"Duración\", \"value\": \"2 o 3 horas\"}, {\"label\": \"Horario\", \"value\": \"Fuera de apertura\"}], \"fr\": [{\"label\": \"Durée\", \"value\": \"2 ou 3 heures\"}, {\"label\": \"Horaires\", \"value\": \"Hors ouverture\"}]}','{\"unit\": \"kids\", \"zones\": [{\"label\": \"Kids\", \"accent\": \"kids\", \"durations\": [{\"tiers\": [{\"size\": 30, \"weekday\": 1200, \"weekend\": 1400}, {\"size\": 75, \"weekday\": 1100, \"weekend\": 1300}, {\"size\": 100, \"weekday\": 1000, \"weekend\": 1200}], \"minutes\": 120}, {\"tiers\": [{\"size\": 30, \"weekday\": 1500, \"weekend\": 1700}, {\"size\": 75, \"weekday\": 1400, \"weekend\": 1600}, {\"size\": 100, \"weekday\": 1200, \"weekend\": 1400}], \"minutes\": 180}]}, {\"label\": \"Jump\", \"accent\": \"jump\", \"durations\": [{\"tiers\": [{\"size\": 30, \"weekday\": 1500, \"weekend\": 1700}, {\"size\": 75, \"weekday\": 1400, \"weekend\": 1600}, {\"size\": 100, \"weekday\": 1200, \"weekend\": 1400}], \"minutes\": 120}, {\"tiers\": [{\"size\": 30, \"weekday\": 1800, \"weekend\": 2000}, {\"size\": 75, \"weekday\": 1600, \"weekend\": 1800}, {\"size\": 100, \"weekday\": 1500, \"weekend\": 1700}], \"minutes\": 180}]}]}','{\"en\": \"2- or 3-hour sessions\", \"es\": \"Sesiones de 2 o 3 h\", \"fr\": \"Séances de 2 ou 3 h\"}','images/attractions/kids_zone.webp',NULL,1,1,1,'2026-08-19 14:04:30','2026-08-19 14:04:30'),(2,'teambuilding','{\"en\": \"Team\", \"es\": \"Equipo\", \"fr\": \"Équipe\"}','{\"en\": \"Companies\", \"es\": \"Empresas\", \"fr\": \"Entreprises\"}','{\"en\": \"Team days: cohesion, cooperative games and plenty of action, with the park to yourselves outside regular hours. Bookings from 30 people; we tailor the duration and activities to your company.\", \"es\": \"Jornadas para equipos: cohesión, juegos cooperativos y mucha actividad física, con el parque para vosotros fuera del horario habitual. Reservas a partir de 30 personas; adaptamos la duración y las dinámicas a tu empresa.\", \"fr\": \"Journées pour les équipes : cohésion, jeux coopératifs et beaucoup d\'action, avec le parc rien que pour vous en dehors des horaires habituels. Réservations à partir de 30 personnes ; on adapte la durée et les activités à ton entreprise.\"}','{\"en\": \"Whole park\", \"es\": \"Parque completo\", \"fr\": \"Parc entier\"}','{\"en\": [{\"label\": \"Group\", \"value\": \"Minimum 30 people\"}, {\"label\": \"Hours\", \"value\": \"Outside opening\"}], \"es\": [{\"label\": \"Grupo\", \"value\": \"Mínimo 30 personas\"}, {\"label\": \"Horario\", \"value\": \"Fuera de apertura\"}], \"fr\": [{\"label\": \"Groupe\", \"value\": \"Minimum 30 personnes\"}, {\"label\": \"Horaires\", \"value\": \"Hors ouverture\"}]}','{\"unit\": \"people\", \"zones\": [{\"label\": \"Jump\", \"accent\": \"jump\", \"durations\": [{\"tiers\": [{\"size\": 30, \"weekday\": 1500, \"weekend\": 1700}, {\"size\": 75, \"weekday\": 1400, \"weekend\": 1600}, {\"size\": 100, \"weekday\": 1200, \"weekend\": 1400}], \"minutes\": 120}, {\"tiers\": [{\"size\": 30, \"weekday\": 1800, \"weekend\": 2000}, {\"size\": 75, \"weekday\": 1600, \"weekend\": 1800}, {\"size\": 100, \"weekday\": 1500, \"weekend\": 1700}], \"minutes\": 180}]}]}','{\"en\": \"From 30 people\", \"es\": \"Desde 30 personas\", \"fr\": \"À partir de 30 personnes\"}','images/attractions/park_jump.webp',NULL,2,1,1,'2026-08-19 14:04:30','2026-08-19 14:04:30'),(3,'sesionadultos','{\"en\": \"Night\", \"es\": \"Noche\", \"fr\": \"Nuit\"}','{\"en\": \"Adults outing\", \"es\": \"Excursión para mayores\", \"fr\": \"Sortie adultes\"}','{\"en\": \"We open the park for adult groups only, from 22:00 to 01:00: jumping without kids, music and a relaxed vibe. Bookings from 30 people.\", \"es\": \"Abrimos el parque solo para grupos de adultos, de 22:00 a 01:00: saltos sin niños, música y ambiente relajado. Reservas a partir de 30 personas.\", \"fr\": \"On ouvre le parc uniquement pour les groupes d\'adultes, de 22h00 à 01h00 : sauts sans enfants, musique et ambiance détendue. Réservations à partir de 30 personnes.\"}','{\"en\": \"Whole park\", \"es\": \"Parque completo\", \"fr\": \"Parc entier\"}','{\"en\": [{\"label\": \"Hours\", \"value\": \"22:00 – 01:00\"}, {\"label\": \"Group\", \"value\": \"Minimum 30 people\"}], \"es\": [{\"label\": \"Horario\", \"value\": \"22:00 – 01:00\"}, {\"label\": \"Grupo\", \"value\": \"Mínimo 30 personas\"}], \"fr\": [{\"label\": \"Horaires\", \"value\": \"22h00 – 01h00\"}, {\"label\": \"Groupe\", \"value\": \"Minimum 30 personnes\"}]}',NULL,'{\"en\": \"22:00–01:00 · min. 30\", \"es\": \"22:00–01:00 · mín. 30\", \"fr\": \"22h00–01h00 · min. 30\"}','images/attractions/jump_saltos_libres.webp',NULL,3,1,1,'2026-08-19 14:04:30','2026-08-19 14:04:30');
