INSERT INTO `legal_document_versions` (`id`, `slug`, `locale`, `version`, `title`, `body`, `body_hash`, `published_by`, `published_at`, `created_at`) VALUES (1,'waiver','es',1,'Exención de responsabilidad','[{\"h\": \"Condiciones\", \"p\": \"Texto de prueba local para reproducir el aviso. Versión uno.\"}]','2fdea154a6b8f2a5d6c86c24686b6549b55a1af7e22fa01c2bc2edc7f90cdc82',NULL,'2026-09-01 14:18:17','2026-09-01 14:18:17'),(2,'waiver','en',1,'Liability waiver','[{\"h\": \"Condiciones\", \"p\": \"Texto de prueba local para reproducir el aviso. Versión uno.\"}]','e8fd711f34b9001eaf19e1f6f268ab942f7b427dc1bfdf853338fb3a597ab2da',NULL,'2026-09-01 14:18:17','2026-09-01 14:18:17'),(3,'waiver','fr',1,'Décharge de responsabilité','[{\"h\": \"Condiciones\", \"p\": \"Texto de prueba local para reproducir el aviso. Versión uno.\"}]','41645d43829731d381ecd4ffae77ed9862372ba89b0885b904d74c53d9a24e6c',NULL,'2026-09-01 14:18:17','2026-09-01 14:18:17'),(5,'condiciones','en',1,'Terms of use and purchase','[{\"h\": \"1. Purpose and acceptance\", \"p\": \"These Terms of use and purchase (the \\\"Terms\\\") govern access to and use of this website, as well as the online purchase of tickets and the booking of birthday parties and events at Play Jump Park. By using the website, registering an account or placing an order, you declare that you have read and accepted these Terms. If you do not agree with them, you must not use the website or buy through it. We may update these Terms to reflect legal or operational changes; the version applicable to you is the one in force at the time of your purchase, which you accept by ticking the relevant box when you register.\"}, {\"h\": \"2. Owner and contact details\", \"p\": \"The owner of the website and seller is Play Jump Park S.L., tax ID B22670053, registered at Calle Los Alcázares, 13, 30562 Ceutí (Murcia). For any query, complaint or to exercise rights relating to the website or your order, you can write to us at info@playjump.es or call us on +34 641 99 57 14.\"}, {\"h\": \"3. User account\", \"p\": \"To book and buy you need to create an account by providing your name, email and phone number, and choosing a password. You agree to provide accurate, up-to-date information and to keep your password confidential; you are responsible for activity carried out from your account. The account is activated once your email has been verified. Important: the \\\"park registration\\\" and the liability waiver are NOT handled on this website, but on an external system managed by the owner; where applicable, you will access it via the link provided to you. This website does not collect or store the waiver.\"}, {\"h\": \"4. Products and services\", \"p\": \"Through the website you can buy tickets tied to time slots with limited capacity, as well as birthday and event packs, which may include optional add-ons. Birthday packs may require a minimum number of guests and, where indicated on the product page, the payment of a deposit. The description, conditions and availability of each product are those shown on its page at the time of purchase. We aim to keep the information accurate, but typographical or availability errors may occur; in that case we will inform you and, if necessary, cancel and refund the affected order.\"}, {\"h\": \"5. Prices and taxes\", \"p\": \"Prices are shown in euros (€) and include the applicable VAT, calculated at the rate configured in the system (21 %). Some products are advertised \\\"from X €\\\", which is the starting price depending on the slot, rate or date; the final price applicable to you is the one shown in your order details before payment. The prices in force are those published at the time the purchase is made.\"}, {\"h\": \"6. Purchase process and confirmation\", \"p\": \"To complete a purchase you must select the product and, where applicable, the time slot, review your order details and total, and accept these Terms before paying. Your place is held for a limited time while you complete payment; if payment is not completed within that period, the order expires and the place is automatically released. The contract is formed when payment is confirmed, at which point you will receive your confirmation and, where applicable, your tickets with their access code.\"}, {\"h\": \"7. Payment\", \"p\": \"Payment is made through the secure bank gateway Redsys. Your card details are entered directly in the Redsys environment and processed by that provider: we do not store your card number. We only keep the information needed to manage and reconcile the charge (for example, amount, transaction identifier and authorisation code). If the charge is declined or not completed, the order will not be deemed confirmed.\"}, {\"h\": \"8. Capacity and time slots\", \"p\": \"Tickets and bookings are subject to availability and to the capacity of each time slot. Buying a ticket for a particular slot does not grant access outside that slot. The owner may change opening hours, close dates or adjust capacity for operational, maintenance or safety reasons; if this affects a confirmed booking, you will be offered an alternative or the corresponding refund.\"}, {\"h\": \"9. Guest data for birthday parties\", \"p\": \"For birthday packs we may ask, through a form, for the details of each guest (for example, name, allergies or intolerances, special menu and notes), for the sole purpose of organising the event and ensuring food safety. This data may relate to minors and to health information (allergies/intolerances). It must be the contracting adult who provides it, ensuring they are entitled to do so and, where applicable, having the consent of the parents or guardians. The exact set of data requested is the one indicated by the form in each case.\"}, {\"h\": \"10. Cancellations and refunds\", \"p\": \"Changes and cancellations to an order are handled by park staff at your request (via info@playjump.es or at the park itself); there is no self-service cancellation from your account. Where a change involves an additional amount, this is paid in person at the park. Where a change or cancellation reduces the amount of an order that has already been paid, an automatic partial refund is made to the same means of payment used for the purchase. The deadlines to cancel or change, the treatment of no-shows and whether the birthday pack deposit is refundable are governed by the park\'s cancellation policy: you may cancel or change your birthday booking up to 3 calendar days before the booked date, in which case the deposit is refunded in full; with less than 3 days\' notice, or if you do not show up on the booked date (no-show), the deposit is non-refundable.\"}, {\"h\": \"11. User obligations and conduct\", \"p\": \"You agree to use the website and services lawfully and in accordance with these Terms, not to provide false data and not to use tickets fraudulently. Within the park you must at all times follow the rules of use and safety and the instructions of staff. You can consult the Park rules on the website; breaching them may lead to access being refused or withdrawn, with no right to a refund.\"}, {\"h\": \"12. Liability and service availability\", \"p\": \"We aim to keep the website available and its information accurate and up to date, but we cannot guarantee that it will be free of interruptions or errors. We may temporarily suspend access for maintenance or technical reasons. We are not liable for damages arising from improper use of the website or services, nor for force majeure events beyond our control. Nothing in these Terms limits liability that cannot legally be excluded.\"}, {\"h\": \"13. Intellectual property\", \"p\": \"The website content (texts, images, logos, trademarks and design) belongs to its owner or its licensors and is protected by intellectual and industrial property law. Its reproduction, distribution or use without prior authorisation is not permitted.\"}, {\"h\": \"14. Data protection\", \"p\": \"The processing of your personal data is governed by our Privacy policy, which you can consult on the website and which sets out the purposes, legal bases, retention periods and how to exercise your rights. By accepting these Terms, you declare that you have been informed of that Policy.\"}, {\"h\": \"15. Applicable law and dispute resolution\", \"p\": \"These Terms are governed by Spanish law. If you act as a consumer, you may bring a claim before the courts of your place of residence. In any other case, the parties submit to the courts of Murcia. As a consumer, you may also use the European Commission\'s online dispute resolution platform, available at https://ec.europa.eu/consumers/odr.\"}]','7761546128f4cbb59942466022bc9e7863dac5987c8a118b587f8554b2f9326c',NULL,'2026-09-02 17:48:35','2026-09-02 17:48:35'),(6,'condiciones','es',1,'Condiciones de uso y compra','[{\"h\": \"1. Objeto y aceptación\", \"p\": \"Estas Condiciones de uso y compra (en adelante, las «Condiciones») regulan el acceso y el uso de esta web, así como la compra en línea de entradas y la reserva de cumpleaños y eventos de Play Jump Park. Al utilizar la web, registrar una cuenta o realizar un pedido, declaras haber leído y aceptado estas Condiciones. Si no estás de acuerdo con ellas, no debes usar la web ni comprar a través de ella. Podemos actualizar estas Condiciones para adaptarlas a cambios legales u operativos; te será de aplicación la versión vigente en el momento de tu compra, que aceptas marcando la casilla correspondiente al registrarte.\"}, {\"h\": \"2. Titular y datos de contacto\", \"p\": \"El titular de la web y responsable de la venta es Play Jump Park S.L., con NIF B22670053 y domicilio en Calle Los Alcázares, 13, 30562 Ceutí (Murcia). Para cualquier consulta, reclamación o ejercicio de derechos relacionados con la web o tu pedido puedes escribirnos a info@playjump.es o llamarnos al +34 641 99 57 14.\"}, {\"h\": \"3. Cuenta de usuario\", \"p\": \"Para reservar y comprar necesitas crear una cuenta facilitando tu nombre, correo electrónico y teléfono, y elegir una contraseña. Te comprometes a aportar datos veraces y actualizados y a mantener la confidencialidad de tu contraseña; eres responsable de la actividad realizada desde tu cuenta. La cuenta se activa una vez verificado tu correo electrónico. Importante: el «registro del parque» y la exención de responsabilidad (waiver) NO se gestionan en esta web, sino en un sistema externo gestionado por el titular; cuando proceda, accederás a él desde el enlace que se te facilite. Esta web no recoge ni almacena el waiver.\"}, {\"h\": \"4. Productos y servicios\", \"p\": \"A través de la web puedes adquirir entradas asociadas a franjas horarias con aforo limitado, así como packs de cumpleaños y eventos, que pueden incluir complementos opcionales. Los packs de cumpleaños pueden requerir un número mínimo de invitados y, según se indique en la ficha del producto, el abono de una señal. La descripción, las condiciones y la disponibilidad de cada producto son las que figuran en su ficha en el momento de la compra. Procuramos que la información sea correcta, pero pueden producirse errores tipográficos o de disponibilidad; en tal caso te informaremos y, si fuera necesario, anularemos y reembolsaremos el pedido afectado.\"}, {\"h\": \"5. Precios e impuestos\", \"p\": \"Los precios se muestran en euros (€) e incluyen el IVA aplicable, calculado al tipo configurado en el sistema (21 %). Algunos productos se anuncian con la indicación «desde X €», que corresponde al precio de partida según la franja, la tarifa o la fecha; el precio final aplicable es el que se te muestra en el detalle del pedido antes de pagar. Los precios vigentes son los publicados en el momento de formalizar la compra.\"}, {\"h\": \"6. Proceso de compra y confirmación\", \"p\": \"Para completar una compra debes seleccionar el producto y, en su caso, la franja horaria, revisar el detalle y el total de tu pedido y aceptar estas Condiciones antes de pagar. La plaza queda retenida durante un tiempo limitado mientras completas el pago; si no se completa dentro de ese plazo, el pedido caduca y la plaza se libera automáticamente. El contrato se entiende perfeccionado cuando se confirma el pago, momento en el que recibirás la confirmación y, cuando proceda, las entradas con su código de acceso.\"}, {\"h\": \"7. Pago\", \"p\": \"El pago se realiza a través de la pasarela bancaria segura Redsys. Los datos de tu tarjeta se introducen directamente en el entorno de Redsys y son tratados por dicho proveedor: nosotros no almacenamos el número de tu tarjeta. Solo conservamos la información necesaria para gestionar y conciliar el cobro (por ejemplo, importe, identificador y código de autorización de la operación). Si el cargo es rechazado o no se completa, el pedido no se considerará confirmado.\"}, {\"h\": \"8. Aforo y franjas horarias\", \"p\": \"Las entradas y reservas están sujetas a disponibilidad y al aforo de cada franja horaria. La compra de una entrada para una franja concreta no garantiza el acceso fuera de esa franja. El titular puede modificar horarios, cerrar fechas o ajustar el aforo por motivos operativos, de mantenimiento o de seguridad; si ello afecta a una reserva ya confirmada, se te ofrecerá una alternativa o el reembolso correspondiente.\"}, {\"h\": \"9. Datos de los invitados en cumpleaños\", \"p\": \"Para los packs de cumpleaños podemos solicitar, mediante un formulario, los datos de cada invitado (por ejemplo, nombre, alergias o intolerancias, menú especial y observaciones), con la única finalidad de organizar el evento y garantizar la seguridad alimentaria. Estos datos pueden referirse a menores y a información de salud (alergias/intolerancias). Debe ser el adulto contratante quien los aporte, garantizando que está legitimado para ello y, cuando corresponda, contando con el consentimiento de los responsables parentales. El conjunto exacto de datos solicitados es el que indique el formulario en cada caso.\"}, {\"h\": \"10. Cancelaciones y reembolsos\", \"p\": \"Las modificaciones y cancelaciones de un pedido las gestiona el personal del parque a petición tuya (a través de info@playjump.es o en el propio parque); no existe un autoservicio de cancelación desde tu cuenta. Cuando una modificación supone un importe adicional, este se abona en persona en el parque. Cuando una modificación o cancelación reduce el importe de un pedido ya pagado, se realiza un reembolso parcial automático al mismo medio de pago utilizado en la compra. Los plazos para cancelar o modificar, el tratamiento de las ausencias (no presentarse) y el carácter reembolsable o no de la señal de los packs de cumpleaños se rigen por la política de cancelación del parque: puedes cancelar o modificar tu reserva de cumpleaños hasta 3 días naturales antes de la fecha reservada y, en ese caso, la señal se reembolsa íntegramente; con menos de 3 días de antelación, o si no te presentas el día reservado (no-show), la señal no es reembolsable.\"}, {\"h\": \"11. Obligaciones y conducta del usuario\", \"p\": \"Te comprometes a usar la web y los servicios de forma lícita y conforme a estas Condiciones, a no facilitar datos falsos ni utilizar las entradas de forma fraudulenta. Dentro del parque debes respetar en todo momento las normas de uso y de seguridad y las indicaciones del personal. Puedes consultar las Normas del parque en la web; su incumplimiento puede conllevar la denegación o la retirada del acceso, sin derecho a reembolso.\"}, {\"h\": \"12. Responsabilidad y disponibilidad del servicio\", \"p\": \"Procuramos que la web esté disponible y que su información sea correcta y esté actualizada, pero no podemos garantizar la ausencia de interrupciones o errores. Podremos suspender temporalmente el acceso por mantenimiento o por causas técnicas. No respondemos de los daños derivados de un uso indebido de la web o de los servicios, ni de causas de fuerza mayor ajenas a nuestro control. Nada en estas Condiciones limita la responsabilidad que legalmente no pueda excluirse.\"}, {\"h\": \"13. Propiedad intelectual\", \"p\": \"Los contenidos de la web (textos, imágenes, logotipos, marcas y diseño) pertenecen a su titular o a sus licenciantes y están protegidos por la normativa de propiedad intelectual e industrial. No se permite su reproducción, distribución ni uso sin autorización previa.\"}, {\"h\": \"14. Protección de datos\", \"p\": \"El tratamiento de tus datos personales se rige por nuestra Política de privacidad, que puedes consultar en la web y donde se detallan las finalidades, las bases jurídicas, los plazos de conservación y cómo ejercer tus derechos. Al aceptar estas Condiciones declaras haber sido informado de dicha Política.\"}, {\"h\": \"15. Legislación aplicable y resolución de conflictos\", \"p\": \"Estas Condiciones se rigen por la legislación española. Si actúas como consumidor, podrás reclamar ante los juzgados y tribunales de tu lugar de domicilio. Para cualquier otro supuesto, las partes se someten a los juzgados y tribunales de Murcia. Como consumidor, también puedes acudir a la plataforma europea de resolución de litigios en línea de la Comisión Europea, disponible en https://ec.europa.eu/consumers/odr.\"}]','8c4defec5b4a9dbe43943a214c73e6c64c4b034d61e4b16c61af1f27e98203fa',NULL,'2026-09-02 17:48:35','2026-09-02 17:48:35'),(7,'condiciones','fr',1,'Conditions d\'utilisation et d\'achat','[{\"h\": \"1. Objet et acceptation\", \"p\": \"Ces Conditions d\'utilisation et d\'achat (les « Conditions ») régissent l\'accès et l\'utilisation de ce site, ainsi que l\'achat en ligne de billets et la réservation d\'anniversaires et d\'événements chez Play Jump Park. En utilisant le site, en créant un compte ou en passant une commande, tu déclares avoir lu et accepté ces Conditions. Si tu n\'es pas d\'accord, tu ne dois ni utiliser le site ni y acheter. Nous pouvons mettre à jour ces Conditions pour les adapter à des changements légaux ou opérationnels ; la version qui s\'applique à toi est celle en vigueur au moment de ton achat, que tu acceptes en cochant la case correspondante lors de l\'inscription.\"}, {\"h\": \"2. Éditeur et coordonnées\", \"p\": \"L\'éditeur du site et vendeur est Play Jump Park S.L., NIF B22670053, domicilié à Calle Los Alcázares, 13, 30562 Ceutí (Murcia). Pour toute question, réclamation ou exercice de tes droits liés au site ou à ta commande, tu peux nous écrire à info@playjump.es ou nous appeler au +34 641 99 57 14.\"}, {\"h\": \"3. Compte utilisateur\", \"p\": \"Pour réserver et acheter, tu dois créer un compte en fournissant ton nom, ton email et ton téléphone, et en choisissant un mot de passe. Tu t\'engages à fournir des données exactes et à jour et à garder ton mot de passe confidentiel ; tu es responsable de l\'activité réalisée depuis ton compte. Le compte est activé une fois ton email vérifié. Important : l\'« inscription du parc » et la décharge de responsabilité (waiver) NE sont PAS gérées sur ce site, mais sur un système externe géré par l\'éditeur ; le cas échéant, tu y accéderas via le lien qui te sera fourni. Ce site ne collecte ni ne conserve la décharge.\"}, {\"h\": \"4. Produits et services\", \"p\": \"Sur le site, tu peux acheter des billets associés à des créneaux horaires à capacité limitée, ainsi que des packs d\'anniversaire et d\'événements, qui peuvent inclure des compléments optionnels. Les packs d\'anniversaire peuvent exiger un nombre minimum d\'invités et, selon ce qu\'indique la fiche du produit, le versement d\'un acompte. La description, les conditions et la disponibilité de chaque produit sont celles figurant sur sa fiche au moment de l\'achat. Nous veillons à l\'exactitude de l\'information, mais des erreurs typographiques ou de disponibilité peuvent survenir ; le cas échéant, nous t\'en informerons et, si nécessaire, annulerons et rembourserons la commande concernée.\"}, {\"h\": \"5. Prix et taxes\", \"p\": \"Les prix sont affichés en euros (€) et incluent la TVA applicable, calculée au taux configuré dans le système (21 %). Certains produits sont annoncés « à partir de X € », ce qui correspond au prix de départ selon le créneau, le tarif ou la date ; le prix final qui t\'est applicable est celui affiché dans le détail de ta commande avant le paiement. Les prix en vigueur sont ceux publiés au moment de finaliser l\'achat.\"}, {\"h\": \"6. Processus d\'achat et confirmation\", \"p\": \"Pour finaliser un achat, tu dois sélectionner le produit et, le cas échéant, le créneau horaire, vérifier le détail et le total de ta commande et accepter ces Conditions avant de payer. Ta place est réservée pendant un temps limité le temps de finaliser le paiement ; si celui-ci n\'est pas effectué dans ce délai, la commande expire et la place est automatiquement libérée. Le contrat est conclu lorsque le paiement est confirmé ; tu reçois alors ta confirmation et, le cas échéant, tes billets avec leur code d\'accès.\"}, {\"h\": \"7. Paiement\", \"p\": \"Le paiement s\'effectue via la passerelle bancaire sécurisée Redsys. Les données de ta carte sont saisies directement dans l\'environnement de Redsys et traitées par ce prestataire : nous ne stockons pas le numéro de ta carte. Nous ne conservons que les informations nécessaires pour gérer et rapprocher le paiement (par exemple, montant, identifiant et code d\'autorisation de l\'opération). Si le débit est refusé ou non finalisé, la commande ne sera pas considérée comme confirmée.\"}, {\"h\": \"8. Capacité et créneaux horaires\", \"p\": \"Les billets et réservations sont soumis à disponibilité et à la capacité de chaque créneau horaire. L\'achat d\'un billet pour un créneau précis ne garantit pas l\'accès en dehors de ce créneau. L\'éditeur peut modifier les horaires, fermer des dates ou ajuster la capacité pour des raisons opérationnelles, de maintenance ou de sécurité ; si cela affecte une réservation confirmée, une alternative ou le remboursement correspondant te sera proposé.\"}, {\"h\": \"9. Données des invités pour les anniversaires\", \"p\": \"Pour les packs d\'anniversaire, nous pouvons demander, via un formulaire, les données de chaque invité (par exemple, nom, allergies ou intolérances, menu spécial et observations), à la seule fin d\'organiser l\'événement et de garantir la sécurité alimentaire. Ces données peuvent concerner des mineurs et des informations de santé (allergies/intolérances). C\'est à l\'adulte contractant de les fournir, en garantissant qu\'il est habilité à le faire et, le cas échéant, en disposant du consentement des responsables parentaux. L\'ensemble exact des données demandées est celui indiqué par le formulaire dans chaque cas.\"}, {\"h\": \"10. Annulations et remboursements\", \"p\": \"Les modifications et annulations d\'une commande sont gérées par le personnel du parc à ta demande (via info@playjump.es ou au parc lui-même) ; il n\'existe pas d\'annulation en libre-service depuis ton compte. Lorsqu\'une modification implique un montant supplémentaire, celui-ci est réglé en personne au parc. Lorsqu\'une modification ou une annulation réduit le montant d\'une commande déjà payée, un remboursement partiel automatique est effectué sur le même moyen de paiement utilisé lors de l\'achat. Les délais pour annuler ou modifier, le traitement des absences (no-show) et le caractère remboursable ou non de l\'acompte des packs d\'anniversaire sont régis par la politique d\'annulation du parc : tu peux annuler ou modifier ta réservation d\'anniversaire jusqu\'à 3 jours calendaires avant la date réservée, auquel cas l\'acompte est intégralement remboursé ; avec moins de 3 jours de préavis, ou si tu ne te présentes pas à la date réservée (no-show), l\'acompte n\'est pas remboursable.\"}, {\"h\": \"11. Obligations et conduite de l\'utilisateur\", \"p\": \"Tu t\'engages à utiliser le site et les services de façon licite et conforme à ces Conditions, à ne pas fournir de données fausses et à ne pas utiliser les billets de manière frauduleuse. Dans le parc, tu dois respecter à tout moment les règles d\'utilisation et de sécurité et les consignes du personnel. Tu peux consulter les Règles du parc sur le site ; leur non-respect peut entraîner le refus ou le retrait de l\'accès, sans droit à remboursement.\"}, {\"h\": \"12. Responsabilité et disponibilité du service\", \"p\": \"Nous veillons à la disponibilité du site et à l\'exactitude et l\'actualité de son information, mais nous ne pouvons garantir l\'absence d\'interruptions ou d\'erreurs. Nous pouvons suspendre temporairement l\'accès pour maintenance ou pour des raisons techniques. Nous ne répondons pas des dommages résultant d\'un usage abusif du site ou des services, ni des cas de force majeure échappant à notre contrôle. Rien dans ces Conditions ne limite la responsabilité qui ne peut légalement être exclue.\"}, {\"h\": \"13. Propriété intellectuelle\", \"p\": \"Les contenus du site (textes, images, logos, marques et design) appartiennent à son éditeur ou à ses concédants et sont protégés par le droit de la propriété intellectuelle et industrielle. Leur reproduction, distribution ou utilisation sans autorisation préalable n\'est pas permise.\"}, {\"h\": \"14. Protection des données\", \"p\": \"Le traitement de tes données personnelles est régi par notre Politique de confidentialité, que tu peux consulter sur le site et qui détaille les finalités, les bases juridiques, les durées de conservation et la façon d\'exercer tes droits. En acceptant ces Conditions, tu déclares avoir été informé de cette Politique.\"}, {\"h\": \"15. Droit applicable et résolution des litiges\", \"p\": \"Ces Conditions sont régies par le droit espagnol. Si tu agis en tant que consommateur, tu pourras saisir les tribunaux de ton lieu de domicile. Dans tout autre cas, les parties se soumettent aux tribunaux de Murcia. En tant que consommateur, tu peux aussi recourir à la plateforme européenne de règlement en ligne des litiges de la Commission européenne, disponible sur https://ec.europa.eu/consumers/odr.\"}]','d16ed6143474ec8f676998319950e27380c1543053f3503a3f3fc79c6e5ee0ab',NULL,'2026-09-02 17:48:35','2026-09-02 17:48:35');
