INSERT INTO `opening_hours` (`id`, `weekday`, `open_time`, `close_time`, `is_closed`, `created_at`, `updated_at`) VALUES (1,0,'11:00:00','21:30:00',0,'2026-08-19 14:04:30','2026-08-31 23:59:01'),(2,1,'16:30:00','21:30:00',0,'2026-08-19 14:04:30','2026-08-31 23:59:01'),(3,2,'16:30:00','21:30:00',0,'2026-08-19 14:04:30','2026-08-31 23:59:01'),(4,3,'16:30:00','21:30:00',0,'2026-08-19 14:04:30','2026-08-31 23:59:01'),(5,4,'16:30:00','21:30:00',0,'2026-08-19 14:04:30','2026-08-31 23:59:01'),(6,5,'16:30:00','21:30:00',0,'2026-08-19 14:04:30','2026-08-31 23:59:01'),(7,6,'11:00:00','21:30:00',0,'2026-08-19 14:04:30','2026-08-31 23:59:01');
