/*!40000 ALTER TABLE `park_rules` DISABLE KEYS */;
INSERT INTO `park_rules` (`id`, `name`, `description`, `position`, `is_active`, `created_at`, `updated_at`) VALUES (1,'{\"en\": \"Registration\", \"es\": \"Registro\", \"fr\": \"Inscription\"}','{\"en\": \"If it\'s your first visit, before queueing to enter you must register on our website to approve the park rules and legal terms. For under-16s, the legal guardian completes the registration.\", \"es\": \"Si es tu primera visita, antes de hacer cola para entrar debes registrarte en nuestra web para aprobar las normas del parque y el contenido legal. En el caso de menores de 16 años, el registro lo realiza el/la tutor/a legal.\", \"fr\": \"Lors de ta première visite, avant de faire la queue, tu dois t\'inscrire sur notre site pour approuver le règlement du parc et les mentions légales. Pour les moins de 16 ans, l\'inscription est faite par le tuteur légal.\"}',1,1,'2026-08-19 14:04:30','2026-08-19 14:04:30'),(2,'{\"en\": \"Kids zone\", \"es\": \"Zona Kids\", \"fr\": \"Zone Kids\"}','{\"en\": \"Check the conditions of the centre.\", \"es\": \"Consulta las condiciones del centro.\", \"fr\": \"Consulte les conditions du centre.\"}',2,1,'2026-08-19 14:04:30','2026-08-19 14:04:30'),(3,'{\"en\": \"Jump zone\", \"es\": \"Zona Jump\", \"fr\": \"Zone Jump\"}','{\"en\": \"Entry from age 6 and 1.30 m tall. If the minimum age is met and height is between 1 m and 1.30 m, entry must be with a guardian.\", \"es\": \"Entrada desde los 6 años y 1,30 m de estatura. Si se supera la edad mínima y la estatura está comprendida entre 1 m y 1,30 m, la entrada deberá ser con el/la tutor/a.\", \"fr\": \"Entrée dès 6 ans et 1,30 m. Si l\'âge minimum est atteint et la taille est entre 1 m et 1,30 m, l\'entrée doit se faire avec un tuteur.\"}',3,1,'2026-08-19 14:04:30','2026-08-19 14:04:30'),(4,'{\"en\": \"Conduct\", \"es\": \"Conducta\", \"fr\": \"Conduite\"}','{\"en\": \"Improper use of the facilities, ignoring staff instructions or causing altercations with other users may result in expulsion.\", \"es\": \"Un uso inadecuado de las instalaciones, hacer caso omiso a las indicaciones del Staff o generar altercados con otros usuarios puede ser motivo de expulsión.\", \"fr\": \"Un usage inapproprié des installations, le non-respect des consignes du Staff ou des altercations avec d\'autres usagers peuvent entraîner l\'expulsion.\"}',4,1,'2026-08-19 14:04:30','2026-08-19 14:04:30'),(5,'{\"en\": \"Information\", \"es\": \"Información\", \"fr\": \"Information\"}','{\"en\": \"Feel free to ask our staff about any term or condition regarding rates, promotions, birthdays or anything else.\", \"es\": \"No dudes en consultar con nuestro Staff cualquier término o condición sobre tarifas, promociones, cumpleaños o de otra índole.\", \"fr\": \"N\'hésite pas à demander à notre Staff toute information sur les tarifs, promotions, anniversaires ou autre.\"}',5,1,'2026-08-19 14:04:30','2026-08-19 14:04:30');
/*!40000 ALTER TABLE `park_rules` ENABLE KEYS */;

