INSERT INTO `permissions` (`id`, `name`, `label`, `created_at`, `updated_at`) VALUES (1,'orders.edit_event_data','Editar datos del evento del pedido (homenajeado, edad, notas)','2026-08-19 14:04:27','2026-08-19 14:04:27'),(2,'orders.edit_item','Editar item del pedido (fecha, cantidad, producto, datos, complementos)','2026-08-19 14:04:27','2026-08-19 14:04:27'),(3,'orders.cancel_item','Cancelar item suelto del pedido (con reembolso automático)','2026-08-19 14:04:27','2026-08-19 14:04:27'),(4,'orders.refund_item','Reembolsar item suelto del pedido','2026-08-19 14:04:27','2026-08-19 14:04:27'),(5,'registrations.validate','Validar registro/waiver en puerta','2026-08-19 14:04:32','2026-08-19 14:04:32'),(6,'orders.view','Ver pedidos','2026-08-19 14:04:32','2026-08-19 14:04:32'),(7,'orders.create_manual','Crear pedido manual (back-office)','2026-08-19 14:04:32','2026-08-19 14:04:32'),(8,'orders.cancel','Cancelar pedido','2026-08-19 14:04:32','2026-08-19 14:04:32'),(9,'orders.refund','Reembolsar pedido','2026-08-19 14:04:32','2026-08-19 14:04:32'),(10,'calendar.view','Ver calendario unificado','2026-08-19 14:04:32','2026-08-19 14:04:32'),(11,'users.search_minimal','Búsqueda mínima de usuario (RGPD-safe)','2026-08-19 14:04:32','2026-08-19 14:04:32'),(12,'catalog.manage','Gestionar catálogo (entradas, packs, complementos)','2026-08-19 14:04:32','2026-08-19 14:04:32'),(13,'slots.manage','Gestionar franjas y aforo','2026-08-19 14:04:32','2026-08-19 14:04:32'),(14,'prices.manage','Gestionar tarifas y precios','2026-08-19 14:04:32','2026-08-19 14:04:32'),(15,'content.manage','Gestionar contenido (zonas, atracciones, FAQ, normas, páginas)','2026-08-19 14:04:32','2026-08-19 14:04:32'),(16,'settings.manage','Gestionar configuración y datos fiscales','2026-08-19 14:04:32','2026-08-19 14:04:32'),(17,'users.manage','Crear/editar/borrar usuarios','2026-08-19 14:04:32','2026-08-19 14:04:32'),(18,'users.anonymize','Anonimizar usuario (RGPD)','2026-08-19 14:04:32','2026-08-19 14:04:32'),(19,'consents.view','Ver consentimientos de usuario','2026-08-19 14:04:32','2026-08-19 14:04:32'),(20,'access.manage','Gestionar roles y permisos','2026-08-19 14:04:32','2026-08-19 14:04:32'),(21,'reports.view','Ver informes y exportaciones','2026-08-19 14:04:32','2026-08-19 14:04:32'),(22,'audit.view','Ver registro de auditoría','2026-08-19 14:04:32','2026-08-19 14:04:32'),(23,'waiver.view','Ver el registro probatorio del waiver (firmas y PDF)','2026-08-26 21:27:53','2026-08-26 21:27:53'),(24,'puerta.profile','Ver la ficha de puerta del cliente y registrar su visita','2026-08-31 14:47:40','2026-08-31 14:47:40');
