INSERT INTO `testimonials` (`id`, `text`, `author`, `rating`, `published_at`, `position`, `is_active`, `created_at`, `updated_at`) VALUES (2,'{\"es\": \"Mis hijos salieron encantados y yo pude sentarme un rato. Volvemos seguro.\"}','Ángela M.',5,'2026-07-10',1,1,'2026-09-10 15:35:28','2026-09-10 15:35:28'),(3,'{\"es\": \"Muy limpio y con personal pendiente. La zona de los pequeños está muy bien separada.\"}','Jose Luis R.',5,'2026-05-10',2,1,'2026-09-10 15:35:28','2026-09-10 15:35:28'),(4,'{\"es\": \"Hicimos el cumple de mi hija y nos lo dieron todo hecho. Repetiremos.\"}','Marta S.',4,'2026-02-10',3,1,'2026-09-10 15:35:28','2026-09-10 15:35:28');
